t = 0:0.2:3;
observed = exp(-t/1.5);
candidates = 0.5:0.05:2.5;
loss = zeros(1,numel(candidates));
best_loss = 1e9;
best_tau = 0;
for k = 1:numel(candidates)
    predicted = exp(-t/candidates(k));
    loss(k) = sum((predicted-observed).^2);
    if loss(k) < best_loss
        best_loss = loss(k);
        best_tau = candidates(k);
    end
end
disp([best_tau best_loss]);
assert(abs(best_tau-1.5) < 1e-10);
plot(candidates,loss);
xlabel("Time constant (s)");
ylabel("Sum of squared residuals");

