courses.code:
C = 20;
G = 2;
P = 10;
Ta = 20;
h = 0.5;
assert(C > 0 && G > 0);
tau = C/G;
t = 0:h:50;
T = zeros(1,numel(t));
T(1) = Ta;
for k = 1:numel(t)-1
    rate = (P-G*(T(k)-Ta))/C;
    T(k+1) = T(k)+h*rate;
end
reference = Ta+(P/G)*(1-exp(-t/tau));
max_error = max(abs(T-reference));
equilibrium = Ta+P/G;
disp([T(end) equilibrium max_error]);
assert(max_error < 0.05);
assert(T(1) == Ta);
plot(t,T);
hold("on");
plot(t,reference);
xlabel("Time (s)");
ylabel("Temperature (deg C)");
title("Thermal model and analytical reference");

